def download_plan(root: Path, max_workers: int) -> list[dict[str, Any]]:
    plan = load_plan(root)
    latest = prior_latest(root)
    results = []
    failures = []
    args = [(root, x, latest) for x in plan["objects"]]
    with cf.ThreadPoolExecutor(max_workers=max_workers) as ex:
        futures = {ex.submit(download_one, a): a[1] for a in args}
        for n, fut in enumerate(cf.as_completed(futures), 1):
            obj = futures[fut]
            try: results.append(fut.result())
            except Exception as e: failures.append({"key": obj["key"], "error": repr(e)})
            if n % 500 == 0: print("DOWNLOAD_PROGRESS", n, "OF", len(args), "FAIL", len(failures), flush=True)
    summary = {
        "canonical_id": "P5_PC6_BINANCE_DOWNLOAD_RESULT_V1", "generated_at": now_iso(),
        "plan_sha256": plan["sha256"], "objects_planned": len(args), "objects_succeeded": len(results),
        "objects_failed": len(failures), "failures": failures,
        "raw_zip_bytes": sum(x["raw_byte_size"] for x in results),
    }
    summary["sha256"] = sha_bytes(canonical_bytes(summary))
    atomic_write_once(root / "download_results" / f"result-{summary['sha256']}.json", canonical_bytes(summary))
    atomic_update_pointer(root / "download_results" / "CURRENT", (summary["sha256"] + "\n").encode())
    print(json.dumps({k: summary[k] for k in ("objects_planned","objects_succeeded","objects_failed","raw_zip_bytes","sha256")}, indent=2))
    if failures: raise RuntimeError(f"DOWNLOAD_FAILURES:{len(failures)}")
    return results


def revision_index(root: Path) -> dict[str, dict[str, Any]]:
    return prior_latest(root)


def load_csv_from_revision(rev: dict[str, Any]) -> tuple[list[str] | None, list[list[str]]]:
    raw = Path(rev["raw_storage_locator"]).read_bytes()
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        with z.open(z.namelist()[0]) as f:
            text = io.TextIOWrapper(f, encoding="utf-8", newline="")
            rows = list(csv.reader(text))
    if not rows: return None, []
    first = rows[0]
    if first and first[0] in ("open_time", "calc_time"):
        return first, rows[1:]
    return None, rows


def normalize_timestamp(raw: int, dataset: str, month: str) -> int:
    if dataset == "spot_1h":
        if month < "2025-01":
            if not 1_000_000_000_000 <= raw < 10_000_000_000_000: raise RuntimeError("SPOT_PRE2025_UNIT")
            return raw * 1000
        if not 1_000_000_000_000_000 <= raw < 10_000_000_000_000_000: raise RuntimeError("SPOT_POST2025_UNIT")
        return raw
    if not 1_000_000_000_000 <= raw < 10_000_000_000_000: raise RuntimeError("FUTURES_TIMESTAMP_UNIT")
    return raw * 1000


def normalize_revision(root: Path, rev: dict[str, Any], code_sha: str) -> dict[str, Any]:
    import pandas as pd
    dataset, month, symbol = rev["dataset"], rev["year_month"], rev["symbol"]
    header, rows = load_csv_from_revision(rev)
    ingested_us = iso_to_us(rev["retrieval_timestamp"])
    published_us = iso_to_us(rev.get("source_published_at"))
    out = []
    if dataset in ("futures_1h", "spot_1h"):
        expected = ["open_time","open","high","low","close","volume","close_time","quote_volume",
                    "count","taker_buy_volume","taker_buy_quote_volume","ignore"]
        if header is not None and header != expected: raise RuntimeError(f"KLINE_HEADER:{header}")
        for r in rows:
            if len(r) != 12: raise RuntimeError(f"KLINE_WIDTH:{len(r)}")
            open_us = normalize_timestamp(int(r[0]), dataset, month)
            close_us = normalize_timestamp(int(r[6]), dataset, month)
            out.append({
                "venue":"BINANCE", "market":"USD_M_FUTURES" if dataset=="futures_1h" else "SPOT",
                "dataset":dataset, "symbol":symbol, "month":month,
                "raw_open_time":r[0], "raw_close_time":r[6], "market_event_time_us":close_us,
                "market_observable_at_us":close_us + 1, "p5_ingested_at_us":ingested_us,
                "revision_known_at_us":ingested_us, "source_published_at_us":published_us,
                "open_time_us":open_us, "close_time_us":close_us,
                "open_raw":r[1], "high_raw":r[2], "low_raw":r[3], "close_raw":r[4],
                "volume_raw":r[5], "quote_volume_raw":r[7], "trade_count":int(r[8]),
                "open":float(r[1]), "high":float(r[2]), "low":float(r[3]), "close":float(r[4]),
                "volume":float(r[5]), "quote_volume":float(r[7]),
                "source_revision_id":rev["revision_id"], "source_raw_sha256":rev["raw_sha256"],
                "in_engineering_window":open_us >= START_US,
            })
        keys=[(x["symbol"],x["open_time_us"]) for x in out]
    else:
        expected = ["calc_time","funding_interval_hours","last_funding_rate"]
        if header != expected: raise RuntimeError(f"FUNDING_HEADER:{header}")
        for r in rows:
            if len(r) != 3: raise RuntimeError(f"FUNDING_WIDTH:{len(r)}")
            event_us = normalize_timestamp(int(r[0]), "funding", month)
            out.append({
                "venue":"BINANCE", "market":"USD_M_FUTURES", "dataset":"funding", "symbol":symbol,
                "month":month, "raw_calc_time":r[0], "market_event_time_us":event_us,
                "market_observable_at_us":None, "p5_ingested_at_us":ingested_us,
                "revision_known_at_us":ingested_us, "source_published_at_us":published_us,
                "funding_interval_hours":float(r[1]), "funding_rate_raw":r[2],
                "funding_rate":float(r[2]), "source_revision_id":rev["revision_id"],
                "source_raw_sha256":rev["raw_sha256"], "in_engineering_window":event_us >= START_US,
            })
        keys=[(x["symbol"],x["market_event_time_us"]) for x in out]
    if len(keys) != len(set(keys)): raise RuntimeError(f"DUPLICATE_KEYS:{rev['remote_object_identity']}")
    import pyarrow as pa, pyarrow.parquet as pq
    table = pa.Table.from_pylist(out)
    temp_dir = root / "normalized" / "tmp"; temp_dir.mkdir(parents=True, exist_ok=True)
    fd, temp_name = tempfile.mkstemp(prefix="norm-", suffix=".parquet", dir=temp_dir); os.close(fd)
    temp = Path(temp_name)
    try:
        pq.write_table(table, temp, compression="zstd", use_dictionary=False,
                       write_statistics=True, version="2.6")
        digest = sha_file(temp)
        dest = root / "normalized" / "blobs" / "sha256" / digest[:2] / f"{digest}.parquet"
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.exists():
            if sha_file(dest) != digest: raise RuntimeError("NORMALIZED_BLOB_CONFLICT")
        else:
            os.link(temp, dest)
        result = {
            "source_revision_id":rev["revision_id"], "source_raw_sha256":rev["raw_sha256"],
            "remote_object_identity":rev["remote_object_identity"], "dataset":dataset,
            "symbol":symbol, "month":month, "row_count":len(out),
            "normalized_output_locator":str(dest), "normalized_output_sha256":digest,
            "normalized_byte_size":dest.stat().st_size,
            "transform_code_identity":"git:k3/p5-codex-pc6-binance-data-materialization-v1:quant/p5_track3/binance_materializer.py",
            "transform_code_sha256":code_sha,
            "first_market_event_time_us":min((x["market_event_time_us"] for x in out),default=None),
            "last_market_event_time_us":max((x["market_event_time_us"] for x in out),default=None),
        }
        result["normalization_record_sha256"] = sha_bytes(canonical_bytes(result))
        atomic_write_once(root / "normalized" / "revisions" / f"{result['normalization_record_sha256']}.json",
                          canonical_bytes(result))
        return result
    finally:
        temp.unlink(missing_ok=True)


def normalize_all(root: Path, code_path: Path, max_workers: int) -> list[dict[str, Any]]:
    plan=load_plan(root); latest=revision_index(root); code_sha=sha_file(code_path)
    existing_by_source={x["source_revision_id"]:x for x in load_normalizations(root)}
    revisions=[]
    missing=[]
    for obj in plan["objects"]:
        rev=latest.get(obj["key"])
        if not rev or rev.get("checksum_status") != "VERIFIED_SHA256": missing.append(obj["key"])
        else:
            existing=existing_by_source.get(rev["revision_id"])
            if (existing and Path(existing.get("normalized_output_locator", "")).is_file()
                    and sha_file(Path(existing["normalized_output_locator"])) == existing.get("normalized_output_sha256")):
                continue
            revisions.append(rev)
    if missing: raise RuntimeError(f"RAW_REVISIONS_MISSING:{len(missing)}")
    results=[]; failures=[]; exclusions=[]
    with cf.ThreadPoolExecutor(max_workers=max_workers) as ex:
        futures={ex.submit(normalize_revision,root,rev,code_sha):rev for rev in revisions}
        for n,fut in enumerate(cf.as_completed(futures),1):
            try: results.append(fut.result())
            except Exception as e:
                item={"key":futures[fut]["remote_object_identity"],"error":repr(e)}
                if "DUPLICATE_KEYS:" in str(e):
                    item["classification"]="SOURCE_ARCHIVE_CONFLICT"
                    item["disposition"]="EXCLUDED_AFFECTED_SYMBOL_MONTH; RAW_PRESERVED_UNCHANGED"
                    exclusions.append(item)
                    conflict_sha=sha_bytes(canonical_bytes(item))
                    atomic_write_once(root/"normalized"/"conflicts"/f"{conflict_sha}.json",canonical_bytes(item))
                else:
                    failures.append(item)
            if n % 500 == 0: print("NORMALIZE_PROGRESS",n,"OF",len(revisions),"FAIL",len(failures),flush=True)
    summary={"canonical_id":"P5_PC6_BINANCE_NORMALIZATION_RESULT_V1","generated_at":now_iso(),
             "plan_sha256":plan["sha256"],"objects_planned":len(revisions),"objects_succeeded":len(results),
             "objects_failed":len(failures),"failures":failures,
             "objects_excluded":len(exclusions),"exclusions":exclusions,
             "normalized_bytes":sum(x["normalized_byte_size"] for x in results),"transform_code_sha256":code_sha}
    summary["sha256"]=sha_bytes(canonical_bytes(summary))
    atomic_write_once(root/"normalization_results"/f"result-{summary['sha256']}.json",canonical_bytes(summary))
    atomic_update_pointer(root/"normalization_results"/"CURRENT",(summary["sha256"]+"\n").encode())
    print(json.dumps({k:summary[k] for k in ("objects_planned","objects_succeeded","objects_failed","normalized_bytes","sha256")},indent=2))
    if failures: raise RuntimeError(f"NORMALIZATION_FAILURES:{len(failures)}")
    return results


def load_normalizations(root: Path) -> list[dict[str, Any]]:
    return [json.loads(p.read_text()) for p in sorted((root/"normalized"/"revisions").glob("*.json"))]


def load_normalization_conflicts(root: Path) -> dict[str, dict[str, Any]]:
    return {x["key"]:x for x in (json.loads(p.read_text()) for p in sorted((root/"normalized"/"conflicts").glob("*.json")))}


def artifact(root: Path, out_dir: Path, name: str, value: dict[str, Any]) -> tuple[Path,str]:
    value=dict(value); value["canonical_id"]=name
    data=canonical_bytes(value); actual=sha_bytes(data)
    # Hash is over exact final payload, and is the externally reported artifact hash.
    path=out_dir/f"{name}.json"; atomic_write_once(path,data)
    return path,actual


